class Solution {
    public String shortestPalindrome(String s) {
        String reversed = new StringBuilder(s).reverse().toString();
        String combined = s + "{" + reversed;
        int[] failure = new int[combined.length()];
        for (int i = 1; i < combined.length(); i++) {
            int matched = failure[i - 1];
            while (matched > 0 && combined.charAt(i) != combined.charAt(matched)) {
                matched = failure[matched - 1];
            }
            if (combined.charAt(i) == combined.charAt(matched)) {
                matched++;
            }
            failure[i] = matched;
        }
        int prefixLength = combined.isEmpty() ? 0 : failure[combined.length() - 1];
        return reversed.substring(0, s.length() - prefixLength) + s;
    }
}

class Solution {
    public String shortestPalindrome(String s) {
        String reversed = new StringBuilder(s).reverse().toString();
        String combined = s + "{" + reversed;
        int[] z = zFunction(combined);
        int best = 0;
        for (int i = s.length() + 1; i < combined.length(); i++) {
            if (i + z[i] == combined.length()) {
                best = Math.max(best, z[i]);
            }
        }
        return reversed.substring(0, s.length() - best) + s;
    }

    private int[] zFunction(String text) {
        int[] z = new int[text.length()];
        int left = 0;
        int right = 0;
        for (int i = 1; i < text.length(); i++) {
            if (i <= right) {
                z[i] = Math.min(right - i + 1, z[i - left]);
            }
            while (i + z[i] < text.length()
                    && text.charAt(z[i]) == text.charAt(i + z[i])) {
                z[i]++;
            }
            if (i + z[i] - 1 > right) {
                left = i;
                right = i + z[i] - 1;
            }
        }
        return z;
    }
}

class Solution {
    public String shortestPalindrome(String s) {
        String transformed = transform(s);
        int[] radius = new int[transformed.length()];
        int center = 0;
        int right = 0;
        int best = 0;
        for (int i = 1; i < transformed.length() - 1; i++) {
            int mirror = 2 * center - i;
            if (i < right) {
                radius[i] = Math.min(right - i, radius[mirror]);
            }
            while (transformed.charAt(i + 1 + radius[i])
                    == transformed.charAt(i - 1 - radius[i])) {
                radius[i]++;
            }
            if (i + radius[i] > right) {
                center = i;
                right = i + radius[i];
            }
            if (i - radius[i] == 1) {
                best = Math.max(best, radius[i]);
            }
        }
        String suffix = s.substring(best);
        return new StringBuilder(suffix).reverse().toString() + s;
    }

    private String transform(String s) {
        StringBuilder builder = new StringBuilder("^");
        for (int i = 0; i < s.length(); i++) {
            builder.append('#').append(s.charAt(i));
        }
        builder.append("#$");
        return builder.toString();
    }
}

class Solution {
    public String shortestPalindrome(String s) {
        for (int len = s.length(); len >= 0; len--) {
            if (isPalindromePrefix(s, len)) {
                return new StringBuilder(s.substring(len)).reverse().toString() + s;
            }
        }
        return s;
    }

    private boolean isPalindromePrefix(String s, int len) {
        int left = 0;
        int right = len - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}
